const setThreadPrivacy = `-- name: SetThreadPrivacy :exec
UPDATE thoughts
SET is_private     = $1::bool,
    embedding      = CASE WHEN $1::bool THEN NULL ELSE embedding END,
    embedding_text = CASE WHEN $1::bool THEN NULL ELSE embedding_text END,
    updated_at     = NOW()
WHERE thread_root_id = $2
`

type SetThreadPrivacyParams struct {
	IsPrivate bool        `json:"is_private"`
	RootID    pgtype.UUID `json:"root_id"`
}

// A thread is private or public as a whole. Going private also retracts the
// follow-ups' embeddings, for the same reason the single-thought path does.
func (q *Queries) SetThreadPrivacy(ctx context.Context, arg SetThreadPrivacyParams) error {
	_, err := q.db.Exec(ctx, setThreadPrivacy, arg.IsPrivate, arg.RootID)
	return err
}

