const updateThought = `-- name: UpdateThought :one
UPDATE thoughts
SET
    title = $2,
    content = $3,
    is_private = $4,
    rating = $5,
    updated_at = NOW()
WHERE id = $1
RETURNING id, user_id, book_id, title, content, is_private, rating, created_at, updated_at, embedding, embedding_text, thread_root_id
`

type UpdateThoughtParams struct {
	ID        uuid.UUID   `json:"id"`
	Title     pgtype.Text `json:"title"`
	Content   string      `json:"content"`
	IsPrivate bool        `json:"is_private"`
	Rating    pgtype.Int4 `json:"rating"`
}

func (q *Queries) UpdateThought(ctx context.Context, arg UpdateThoughtParams) (Thought, error) {
	row := q.db.QueryRow(ctx, updateThought,
		arg.ID,
		arg.Title,
		arg.Content,
		arg.IsPrivate,
		arg.Rating,
	)
	var i Thought
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.BookID,
		&i.Title,
		&i.Content,
		&i.IsPrivate,
		&i.Rating,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Embedding,
		&i.EmbeddingText,
		&i.ThreadRootID,
	)
	return i, err
}

